  input         auto_in_b_ready,
  output        auto_in_b_valid,
  output [3:0]  auto_in_b_bits_id,
  output [1:0]  auto_in_b_bits_resp,
  output        auto_in_ar_ready,
  input         auto_in_ar_valid,
  input  [3:0]  auto_in_ar_bits_id,
  input  [28:0] auto_in_ar_bits_addr,
  input  [7:0]  auto_in_ar_bits_len,
  input  [2:0]  auto_in_ar_bits_size,
  input         auto_in_r_ready,
  output        auto_in_r_valid,
  output [3:0]  auto_in_r_bits_id,
  output [31:0] auto_in_r_bits_data,
  output [1:0]  auto_in_r_bits_resp,
  output        auto_out_psel,
                auto_out_penable,
                auto_out_pwrite,
  output [28:0] auto_out_paddr,
  output [31:0] auto_out_pwdata,
  output [3:0]  auto_out_pstrb,
  input         auto_out_pready,
                auto_out_pslverr,
  input  [31:0] auto_out_prdata
);

  wire            nodeOut_penable;
  reg  [1:0]      state;
  wire            _is_write_T = state == 2'h0;
  wire            accept_read = _is_write_T & auto_in_ar_valid;
  wire            accept_write =
    ~accept_read & _is_write_T & auto_in_aw_valid & auto_in_w_valid;
  reg             is_write_r;
  wire            is_write = _is_write_T ? accept_write : is_write_r;
  `ifndef SYNTHESIS
    always @(posedge clock) begin
    end // always @(posedge)
  `endif // not def SYNTHESIS
  reg  [3:0]      rid_reg;
  reg  [3:0]      bid_reg;
  reg  [28:0]     araddr_reg_r;
  reg  [28:0]     awaddr_reg_r;
  reg  [31:0]     wdata_reg_r;
  reg  [3:0]      wstrb_reg_r;
  assign nodeOut_penable = state == 2'h1;
  wire [1:0]      resp = {auto_out_pslverr, 1'h0};
  reg  [1:0]      resp_hold_r;
  wire [1:0]      resp_hold = nodeOut_penable ? resp : resp_hold_r;
  wire            _nodeIn_b_valid_T_2 = state == 2'h2;
  wire            nodeIn_r_valid =
    ~is_write & (nodeOut_penable & auto_out_pready | _nodeIn_b_valid_T_2);
  reg  [31:0]     nodeIn_r_bits_data_r;
  wire            nodeIn_b_valid =
    is_write & (nodeOut_penable & auto_out_pready | _nodeIn_b_valid_T_2);
  wire [3:0][1:0] _GEN =
    {{state},
     {{~(auto_in_r_ready & nodeIn_r_valid | auto_in_b_ready & nodeIn_b_valid), 1'h0}},
     {auto_out_pready
        ? {~(auto_in_r_ready & nodeIn_r_valid | auto_in_b_ready & nodeIn_b_valid), 1'h0}
        : 2'h1},
     {{1'h0, auto_in_ar_valid | auto_in_aw_valid & auto_in_w_valid}}};
  always @(posedge clock) begin
    if (reset)
      state <= 2'h0;
    else
      state <= _GEN[state];
    if (_is_write_T)
      is_write_r <= accept_write;
    if (accept_read) begin
      rid_reg <= auto_in_ar_bits_id;
      araddr_reg_r <= auto_in_ar_bits_addr;
    end
    if (accept_write) begin
      bid_reg <= auto_in_aw_bits_id;
      awaddr_reg_r <= auto_in_aw_bits_addr;
      wdata_reg_r <= auto_in_w_bits_data;
      wstrb_reg_r <= auto_in_w_bits_strb;
    end
    if (nodeOut_penable) begin
      resp_hold_r <= resp;
      nodeIn_r_bits_data_r <= auto_out_prdata;
    end
  end // always @(posedge)
  assign auto_in_aw_ready = accept_write;
  assign auto_in_w_ready = accept_write;
  assign auto_in_b_valid = nodeIn_b_valid;
  assign auto_in_b_bits_id = bid_reg;
  assign auto_in_b_bits_resp = resp_hold;
  assign auto_in_ar_ready = accept_read;
  assign auto_in_r_valid = nodeIn_r_valid;
  assign auto_in_r_bits_id = rid_reg;
  assign auto_in_r_bits_data = nodeOut_penable ? auto_out_prdata : nodeIn_r_bits_data_r;
  assign auto_in_r_bits_resp = resp_hold;
  assign auto_out_psel = accept_read | accept_write | nodeOut_penable;
  assign auto_out_penable = nodeOut_penable;
  assign auto_out_pwrite = is_write;
  assign auto_out_paddr =
    is_write
      ? (accept_write ? auto_in_aw_bits_addr : awaddr_reg_r)
      : accept_read ? auto_in_ar_bits_addr : araddr_reg_r;
  assign auto_out_pwdata = accept_write ? auto_in_w_bits_data : wdata_reg_r;
  assign auto_out_pstrb =
    is_write ? (accept_write ? auto_in_w_bits_strb : wstrb_reg_r) : 4'h0;
endmodule

